//go:build integration

package entstore

import (
	"context"
	"errors"
	"net/url"
	"os"
	"reflect"
	"testing"
	"time"

	"github.com/SAP/astonish/pkg/execution"
	"github.com/SAP/astonish/pkg/store"
	"github.com/google/uuid"
)

// Fail before opening any connection. This gate accepts only the disposable
// loopback container generated by the continuity driver, not an inherited DSN.
func requireTaskPostgres(t *testing.T) {
	t.Helper()
	u, err := url.Parse(os.Getenv("ASTONISH_TEST_DSN"))
	if err != nil || u.Scheme != "postgres" || u.Hostname() != "127.0.0.1" || u.Port() == "" || os.Getenv("ASTONISH_BOTS_TEST_DB_ISOLATED") != "1" || os.Getenv("ASTONISH_TEST_TASK_POSTGRES_OWNED") != "1" {
		t.Fatal("owned disposable loopback PostgreSQL required; use --stage continuity")
	}
}

func TestBotTaskPostgresContinuity(t *testing.T) {
	requireTaskPostgres(t)
	for _, scope := range []store.BotScope{store.BotScopePersonal, store.BotScopeTeam} {
		t.Run(string(scope), func(t *testing.T) {
			f := newPostgresBotServicesFixture(t, scope, 100, 100)
			r := f.repo
			// The physical-byte receipt boundary is tested by the Docker HTTP restart
			// harness; here a trusted test verifier isolates actual PostgreSQL persistence.
			r.taskVerifier = func(context.Context, store.BotTaskPublication, string) error { return nil }
			q := taskTestCandidate(f.run.BotID)
			q.Mutation = store.BotTaskMutation{BotID: f.run.BotID, Lease: f.lease, IdempotencyKey: "continuity-task", AuthorityConstraintRef: "original-owner"}
			p, err := r.PrepareTaskPublication(f.worker, q)
			if err != nil {
				t.Fatal(err)
			}
			task, err := r.CommitTaskPublication(f.worker, store.BotTaskCommitRequest{Mutation: q.Mutation, PublicationID: p.ID, WorkspaceReceiptRef: "trusted-fixture"})
			if err != nil {
				t.Fatal(err)
			}
			var before *store.BotTaskRevision
			t.Run("committed-pin", func(t *testing.T) {
				before, err = r.GetTaskRevision(f.owner, f.run.BotID, *task.Head)
				if err != nil {
					t.Fatal(err)
				}
				if err = r.db.Transaction(f.owner, func(tx botDraftDB) error {
					pin, e := pinTaskHead(f.owner, tx, f.run.BotID, &task.ID)
					if e != nil {
						return e
					}
					if !reflect.DeepEqual(pin, before) {
						t.Error("pin differs from committed revision")
					}
					return nil
				}); err != nil {
					t.Fatal(err)
				}
			})
			// Persist an uncertain external effect WITHOUT executing any external action.
			// Reserving the same identity on reopen must keep the uncertainty, not grant a
			// fresh replay-safe reservation or release the spending ceiling.
			t.Run("uncertain-effect", func(t *testing.T) {
				if _, err = r.ReserveSpend(f.worker, f.q); err != nil {
					t.Fatal(err)
				}
				got, e := r.ResolveSpend(f.worker, store.BotSpendResolution{BotID: f.run.BotID, Key: f.q.Key, Outcome: store.BotSpendOutcomeUnknown, Lease: &f.lease, Evidence: "owned timeout fixture; no external action"})
				if e != nil || got.State != store.BotSpendUncertain {
					t.Fatalf("uncertainty %+v %v", got, e)
				}
			})
			pending := taskTestCandidate(f.run.BotID)
			pending.Mutation = q.Mutation
			pending.Mutation.IdempotencyKey = "pending-before-cancel"
			abandoned, err := r.PrepareTaskPublication(f.worker, pending)
			if err != nil {
				t.Fatal(err)
			}
			action := execution.ActionDescriptor{Tool: "send", Effect: execution.EffectSend, Arguments: []byte(`{}`)}
			digest, _ := action.Digest()
			approval, err := r.RequestApproval(f.worker, f.lease, store.BotApproval{BotID: f.run.BotID, RunID: f.run.ID, Version: f.run.Version, Action: action, ActionDigest: digest, ExpiresAt: time.Now().Add(time.Hour)})
			if err != nil {
				t.Fatal(err)
			}
			t.Run("cancel-approval-revoke", func(t *testing.T) {
				if _, err = r.CancelRun(f.owner, f.run.BotID, f.run.ID); err != nil {
					t.Fatal(err)
				}
				approvals, e := r.ListApprovals(f.owner, f.run.BotID, store.BotPage{Limit: 100})
				if e != nil {
					t.Fatal(e)
				}
				found := false
				for _, a := range approvals {
					if a.ID == approval.ID {
						found = true
						if a.Status != store.ApprovalRevoked {
							t.Fatal("cancel left approval live")
						}
					}
				}
				if !found {
					t.Fatal("approval history lost")
				}
				if _, e = r.CommitTaskPublication(f.worker, store.BotTaskCommitRequest{Mutation: pending.Mutation, PublicationID: abandoned.ID, WorkspaceReceiptRef: "trusted-fixture"}); e == nil {
					t.Fatal("cancelled publication committed")
				}
			})
			f.platform = reopenPreBotPostgres(t, f.platform)
			r = continuityPostgresRepository(t, f.platform, scope, f.owner)
			t.Run("reopen-no-replay", func(t *testing.T) {
				current, e := r.GetTask(f.owner, f.run.BotID, task.ID)
				if e != nil || current.Head == nil || *current.Head != *task.Head {
					t.Fatalf("reopen changed committed head: %v", e)
				}
				approvals, e := r.ListApprovals(f.owner, f.run.BotID, store.BotPage{Limit: 100})
				if e != nil {
					t.Fatal(e)
				}
				revoked := false
				for _, a := range approvals {
					if a.ID == approval.ID {
						revoked = a.Status == store.ApprovalRevoked
					}
				}
				if !revoked {
					t.Fatal("reopen revived or lost revoked approval")
				}
				got, e := r.GetTaskRevision(f.owner, f.run.BotID, *task.Head)
				if e != nil || !reflect.DeepEqual(before, got) {
					t.Fatalf("reopen changed committed bytes: %v", e)
				}
				rec, e := r.db.GetBot(f.owner, f.run.BotID)
				if e != nil {
					t.Fatal(e)
				}
				ledger, e := readBotSpend(rec)
				if e != nil {
					t.Fatal(e)
				}
				if len(ledger.Entries) != 1 || ledger.Entries[f.q.Key].State != store.BotSpendUncertain {
					t.Fatalf("uncertainty lost %+v", ledger)
				}
				if _, e = r.ReserveSpend(f.worker, f.q); e == nil {
					t.Fatal("cancelled worker acquired replay authority")
				}
				r.taskVerifier = func(context.Context, store.BotTaskPublication, string) error { return nil }
				if _, e = r.CommitTaskPublication(f.worker, store.BotTaskCommitRequest{Mutation: pending.Mutation, PublicationID: abandoned.ID, WorkspaceReceiptRef: "trusted-fixture"}); e == nil {
					t.Fatal("restart revived stale publication")
				}
				if _, e = r.GetTaskRevision(f.owner, uuid.New(), *task.Head); !errors.Is(e, store.ErrBotNotFound) {
					t.Fatalf("foreign Bot resolution did not fail scoped: %v", e)
				}
			})
		})
	}
}
